				foreach (var pm in PartMastersAll) {
					sb.Append(string.Format("INSERT INTO partmaster(PartMasterId, PartNumber, ModelCompatibility, PartTypeId, PartsubTypeId, ProductFamily, UseCount) VALUES({0}, '{1}', '{2}', {3}, {4}, '{5}', {6});", pm.PartMasterId, pm.PartNumber, pm.ModelCompatibility, pm.PartTypeId.HasValue ? pm.PartTypeId.Value.ToString() : "null", pm.PartSubtypeId.HasValue ? pm.PartSubtypeId.Value.ToString() : "null", pm.ProductFamily, pm.UseCount));
				}

				db.Database.ExecuteSqlCommand(sb.ToString());
			}
		}
	}
}